export default function baseConcept () {
  const [value, dispatch] = useReducer(handleReducer,"anjass")
  function trigger() {dispatch({})}
  return <>
  <p onClick={trigger}>{value}</p>
  </>
}

function handleReducer(value) {
  return "changed"
}

